// ═══════════════════════════════════════════════════════════
// REGISTRATION LOGIC
// ═══════════════════════════════════════════════════════════

async function registerBatch(resourceId, translations) {
  if (!translations.length) return 0;
  var batchSize = 20;
  var total = 0;
  for (var b = 0; b < translations.length; b += batchSize) {
    var batch = translations.slice(b, b + batchSize);
    try {
      var r = await shopify.graphql(
        'mutation reg($resourceId: ID!, $translations: [TranslationInput!]!) { translationsRegister(resourceId: $resourceId, translations: $translations) { translations { key locale } userErrors { field message } } }',
        { resourceId: resourceId, translations: batch }
      );
      var errors = r.translationsRegister.userErrors || [];
      if (errors.length > 0) {
        for (var e = 0; e < errors.length; e++) console.log('      FOUT: ' + errors[e].message);
        stats.errors.push({ resourceId: resourceId, errors: errors });
      } else {
        total += (r.translationsRegister.translations || []).length;
      }
    } catch (err) {
      console.log('      API FOUT: ' + err.message);
      stats.errors.push({ resourceId: resourceId, error: err.message });
    }
    await sleep(400);
  }
  return total;
}

function findDigest(resource, key) {
  var content = resource.translatableContent || [];
  for (var i = 0; i < content.length; i++) {
    if (content[i].key === key) return content[i].digest;
  }
  return null;
}

function findTitle(resource) {
  var content = resource.translatableContent || [];
  for (var i = 0; i < content.length; i++) {
    if (content[i].key === 'title' && content[i].value) return content[i].value;
  }
  return '';
}

function getBodyMap(title) {
  if (title.indexOf('FlowCore') === 0 && title.indexOf('Travel Pouch') === -1) return FLOWCORE_BODY;
  if (title.indexOf('FlowCore Travel Pouch') === 0) return TRAVEL_POUCH_BODY;
  if (title.indexOf('OralBiome Pro') === 0) return ORALBIOME_BODY;
  if (title.indexOf('LumiCore') === 0) return LUMICORE_BODY;
  if (title.indexOf('CALQIX Priority Support') === 0) return PRIORITY_BODY;
  return null;
}

async function processResource(resource, types) {
  var title = findTitle(resource);
  var label = title || resource.resourceId;
  process.stdout.write('  ' + label.substring(0, 50));

  var allTranslations = [];

  for (var li = 0; li < LOCALES.length; li++) {
    var locale = LOCALES[li];
    var titleMap = TITLE_MAP[locale] || {};
    var typeMap = PRODUCT_TYPE_MAP[locale] || {};

    for (var ci = 0; ci < (resource.translatableContent || []).length; ci++) {
      var item = resource.translatableContent[ci];
      if (!item.digest || !item.value) continue;

      var translated = null;

      if (item.key === 'title') {
        translated = titleMap[item.value] || null;
      } else if (item.key === 'product_type') {
        translated = typeMap[item.value] || null;
      } else if (item.key === 'body_html' || item.key === 'body') {
        // Product body_html
        var bodyMap = getBodyMap(title);
        if (bodyMap && bodyMap[locale]) {
          translated = bodyMap[locale];
        }
        // Collection body_html
        if (!translated && COLLECTION_BODIES[title] && COLLECTION_BODIES[title][locale]) {
          translated = COLLECTION_BODIES[title][locale];
        }
        // Shop policy: contact/legal (small)
        if (!translated && item.value.indexOf('Trade name: CALQIX') !== -1) {
          translated = SHOP_LEGAL_BODY[locale];
        }
      } else if (item.key === 'handle') {
        continue; // Don't translate handles
      }

      if (translated && translated !== item.value) {
        allTranslations.push({
          key: item.key,
          value: translated,
          locale: locale,
          translatableContentDigest: item.digest
        });
      }
    }
  }

  if (allTranslations.length > 0) {
    var count = await registerBatch(resource.resourceId, allTranslations);
    stats.registered += count;
    for (var k = 0; k < LOCALES.length; k++) {
      var lc = LOCALES[k];
      var n = allTranslations.filter(function (t) { return t.locale === lc; }).length;
      stats.perLocale[lc] += n;
    }
    console.log(' => ' + count + ' vertalingen');
  } else {
    stats.skipped++;
    console.log(' => overgeslagen (geen vertaling beschikbaar)');
  }
}

// ═══════════════════════════════════════════════════════════
// MAIN
// ═══════════════════════════════════════════════════════════

async function main() {
  console.log('====================================================');
  console.log('CALQIX \u2014 Volledige Store-Level Vertalingen');
  console.log('Locales: ' + LOCALES.join(', '));
  console.log('Datum: ' + new Date().toLocaleDateString('nl-NL', { day: '2-digit', month: '2-digit', year: 'numeric' }).replace(/\//g, '-'));
  console.log('====================================================');

  var types = ['PRODUCT', 'COLLECTION', 'PAGE', 'SHOP_POLICY', 'LINK', 'MENU'];

  for (var t = 0; t < types.length; t++) {
    var type = types[t];
    var resources = DUMP[type] || [];
    console.log('\n--- ' + type + ' (' + resources.length + ' resources) ---');

    for (var r = 0; r < resources.length; r++) {
      await processResource(resources[r], type);
    }
  }

  console.log('\n====================================================');
  console.log('SAMENVATTING');
  console.log('====================================================');
  console.log('Geregistreerd: ' + stats.registered + ' vertalingen');
  console.log('Overgeslagen:  ' + stats.skipped + ' resources');
  console.log('Per taal:');
  console.log('  sv (Zweeds):       ' + stats.perLocale.sv);
  console.log('  nb (Noors):        ' + stats.perLocale.nb);
  console.log('  da (Deens):        ' + stats.perLocale.da);
  console.log('  fi (Fins):         ' + stats.perLocale.fi);
  console.log('Fouten:            ' + stats.errors.length);

  if (stats.errors.length > 0) {
    console.log('\nFouten:');
    for (var i = 0; i < stats.errors.length; i++) {
      var e = stats.errors[i];
      console.log('  - ' + e.resourceId + ': ' + (e.error || JSON.stringify(e.errors)));
    }
  }
}

main().catch(function (err) {
  console.error('FATAAL:', err.message, err.stack);
  process.exit(1);
});
